css:
.app{box-sizing:border-box;width:100%;height:100%;display:flex;font-family:Inter,Segoe UI,system-ui,sans-serif;color:#1f2433;background:#f5f6fa}
.app *{box-sizing:border-box}
svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.side{width:232px;background:#fff;border-right:1px solid #e6e8ef;padding:16px 12px;display:flex;flex-direction:column;gap:16px}
.logo{display:flex;align-items:center;gap:10px;font-weight:700;font-size:20px;padding:4px 8px 8px}
.mk{width:30px;height:30px;border-radius:8px;background:#4f46e5;color:#fff;font-size:15px;display:flex;align-items:center;justify-content:center}
.nav{display:flex;flex-direction:column;gap:2px}
.it{display:flex;align-items:center;gap:12px;padding:9px 12px;border-radius:8px;font-size:14px;color:#4b5266}
.it.sel{background:#eef0fe;color:#4f46e5;font-weight:600}
.main{flex:1;display:flex;flex-direction:column;min-width:0}
.top{height:64px;display:flex;align-items:center;justify-content:space-between;padding:0 24px;background:#fff;border-bottom:1px solid #e6e8ef}
.title{font-size:20px;font-weight:600}
.rt{display:flex;align-items:center;gap:16px}
.search{display:flex;align-items:center;gap:8px;width:300px;padding:8px 12px;border:1px solid #e1e4ec;border-radius:8px;color:#8b92a5;font-size:13px;background:#fafbfd}
.kbd{margin-left:auto;font-size:11px;border:1px solid #e1e4ec;border-radius:4px;padding:1px 6px;background:#fff}
.bell{color:#4b5266}.bell svg{width:21px;height:21px}
.av{width:34px;height:34px;border-radius:50%;background:#4f46e5;color:#fff;font-size:13px;font-weight:600;display:flex;align-items:center;justify-content:center}
.content{flex:1;padding:24px;display:flex}
.empty{flex:1;background:#fff;border-radius:12px;box-shadow:0 1px 3px rgba(20,24,40,.06);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px}
.ei{width:64px;height:64px;border-radius:50%;background:#eef0fe;color:#4f46e5;display:flex;align-items:center;justify-content:center}
.ei svg{width:30px;height:30px}
.et{font-size:18px;font-weight:600;margin-top:6px}.es{font-size:14px;color:#6b7280}

