function render(root, props, fire) {
  var icons = {
    Dashboard:'<path d="M4 14a8 8 0 0116 0"/><path d="M12 14l4-4"/>',
    Contacts:'<circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0116 0"/>',
    Companies:'<rect x="4" y="3" width="16" height="18" rx="1"/><path d="M9 7h2M13 7h2M9 11h2M13 11h2M10 21v-4h4v4"/>',
    Deals:'<rect x="3" y="7" width="18" height="13" rx="2"/><path d="M9 7V5h6v2"/>',
    Activities:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M3 10h18M8 3v4M16 3v4"/>',
    Tasks:'<rect x="4" y="4" width="16" height="16" rx="2"/><path d="M8 12l3 3 5-6"/>',
    Reports:'<path d="M4 20V10M10 20V4M16 20v-7M21 20H3"/>',
    Settings:'<circle cx="12" cy="12" r="3"/><path d="M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2"/>'
  };
  var html = "";
  Object.keys(icons).forEach(function (k, i) {
    html += '<div class="it' + (i === 0 ? ' sel' : '') + '"><svg viewBox="0 0 24 24">' + icons[k] + '</svg>' + k + '</div>';
  });
  root.querySelector(".nav").innerHTML = html;
}
